import collections,hashlib,json,pathlib,re,subprocess,tomllib
W=pathlib.Path(__file__).resolve().parents[5];P=pathlib.Path(__file__).resolve().parent
A=W/'.flow/artifacts/fn-254-fast-validation-gates-and-a-real-inner'
BASE='6d7cbebe21db55a55e0b9a607e1838dea54173ba'
load=lambda p:json.loads(p.read_text())
sha=lambda b:hashlib.sha256(b).hexdigest()
x=load(P/'inventory-result.json');b=load(A/'task10/revision1/proof/accounting/final-inventory.json')
fields=['package','target_kind','target','test','ignored'];key=lambda x:tuple(x[k] for k in fields)
old=collections.Counter(map(key,b['rust']));cargo=collections.Counter(map(key,x['cargo']));nxt=collections.Counter(map(key,x['nextest']))
assert old<=cargo and cargo==nxt and all(v==1 for v in cargo.values())
added=list((cargo-old).elements());assert len(added)==8 and all('test_run::tests::' in r[3] for r in added)
comparison={'baseline':'task10/revision1/proof/accounting/final-inventory.json','baseline_count':sum(old.values()),'cargo_count':sum(cargo.values()),'nextest_count':sum(nxt.values()),'old_missing':list((old-cargo).elements()),'new_controls':[dict(zip(fields,r)) for r in sorted(added)],'ignored':sum(r['ignored'] for r in x['cargo']),'parity':True,'duplicates':0,'identity_mapping':'All old coordinates identical to task10 revision1 joined inventory, which carries task4 consolidation mapping; no renames in task3.'}
(P/'producer-comparison.json').write_text(json.dumps(comparison,indent=2)+'\n')
previous=load(A/'task10/revision1/proof/snapshot-registry-renewal.json')
for r in previous['snapshot_ui']:assert sha((W/r['path']).read_bytes())==r['sha256'],r['path']
registry={}
for f in ['model/Cargo.lock','model/umpire/Cargo.lock']:
 for p in tomllib.loads((W/f).read_text())['package']:
  if p.get('source','').startswith('registry+'):
   row={k:p[k] for k in ['name','version','source','checksum']};registry[tuple(row.values())]=row
regkey=lambda r:tuple(r[k] for k in ['name','version','source','checksum'])
assert set(map(regkey,registry.values()))==set(map(regkey,previous['registry_tuples']))
locks={f:sha((W/f).read_bytes()) for f in ['model/Cargo.lock','model/umpire/Cargo.lock']}
assert all(subprocess.check_output(['git','show',BASE+':'+f],cwd=W)==(W/f).read_bytes() for f in locks)
(P/'snapshot-registry-renewal.json').write_text(json.dumps({'source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=W,text=True).strip(),'snapshot_ui':previous['snapshot_ui'],'snapshot_count':len(previous['snapshot_ui']),'registry_tuples':list(registry.values()),'registry_count':len(registry),'cargo_lock_sha256':locks,'all_unchanged':True,'update_mode_caveat':'Three baseline trybuild diagnostic paths update under both runners because framework workspace root moved. Generated bytes and both compare-mode red proofs retained; restored task3-generated updates. Producer correction required outside this task.'},indent=2)+'\n')
docs=load(P/'doctest-identities.json');original=load(A/'task4/consolidation-identities.json')['doctests']['cases']
expected={(s.removeprefix('umpire/').split(' ... ')[0].replace(' - compile fail',''),s.endswith('ignored')) for s in original}
assert expected=={(r['test'],r['ignored']) for r in docs['identities']}
for r in docs['identities']:assert subprocess.check_output(['git','show',BASE+':'+r['source']],cwd=W)==(W/r['source']).read_bytes()
docs['exact_previous_name_and_ignored_parity']=True;docs['all_doctest_source_bytes_unchanged']=True
(P/'doctest-identities.json').write_text(json.dumps(docs,indent=2)+'\n')
groups=[]
for name in ['framework','temporal']:
 text=(P/(name+'-groups-all.out')).read_text();assert 'group: jvm (max threads = 1)' in text
 tests=load(P/(name+'-nextest-identities.json'))
 selected=[r for r in tests if (name=='framework' and ((r['package'] in ['umpire-tlc','umpire-apalache','umpire-tla'] and r['target']=='main') or (r['package']=='umpire-fixtures' and r['target']=='fixtures') or (r['package']=='umpire-testing' and r['target_kind']=='lib' and 'actual_tlc_fact_traces_replay_exact_vectors' in r['test']))) or (name=='temporal' and r['package']=='umpire-temporal-tests' and r['target']=='fixtures')]
 section=text.split('group: @global')[0]; observed=set(); binary=None
 for line in section.splitlines():
  match=re.fullmatch(r' {6}(\S+):',line)
  if match:binary=match[1]
  match=re.fullmatch(r' {10}(\S+)',line)
  if match:observed.add((binary,match[1]))
 suites=load(P/(name+'-nextest-list.out'))['rust-suites'].values()
 binaries={(r['package-name'],r['kind'],r['binary-name']):r['binary-id'] for r in suites}
 expected={(binaries[(r['package'],r['target_kind'],r['target'])],r['test']) for r in selected}
 assert expected==observed,(expected-observed,observed-expected)
 groups.append({'workspace':name,'group':'jvm','max_threads':1,'conservative_group_members':selected,'source_routes_reference':'planning/nextest-feasibility/report.md Source-derived JVM candidates','config_parser_and_actual_membership_output':name+'-groups-all.out'})
(P/'jvm-groups.json').write_text(json.dumps({'groups':groups,'host_cpus':12,'host_mem_total_kib':20744944,'host_budget':'One required-backend nextest invocation at a time during task3/task11 proofs. Root combined caller currently sequences framework then Temporal. Group1 x TLC default recovery2 x 512MiB heap = at most 1GiB configured Java heaps per invocation; nonheap and native memory are additional. Separate invocations require coordinated host budget, no host semaphore claimed.','property_worker_source':'model/umpire/backends/tlc/src/runner.rs defaults min(available_parallelism,2); real backend callers do not override. Fake-Java batch controls have their own explicit worker counts.','observed_framework':{k:load(P/'representative.json')[k] for k in ['exit','seconds','java_peak','jvm_test_owner_peak','aggregate_jvm_rss_peak_kib','samples']},'observed_temporal':{k:load(P/'representative-temporal.json')[k] for k in ['exit','seconds','java_peak','jvm_test_owner_peak','aggregate_jvm_rss_peak_kib','samples']}},indent=2)+'\n')
print('954 old +8 new identities; 4 ignored; 5 doctests incl1 ignored; 563 snapshot/UI hashes; 119 registry tuples preserved')
